import{_ as d,o as e,c as a,aS as r}from"./chunks/framework.6vsn32Qq.js";const y=JSON.parse('{"title":"公共能力生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/component-lifecycle.md","filePath":"catalog/component-lifecycle.md","lastUpdated":null}'),o={name:"catalog/component-lifecycle.md"};function c(s,t,i,n,l,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="公共能力生命周期" tabindex="-1">公共能力生命周期 <a class="header-anchor" href="#公共能力生命周期" aria-label="Permalink to &quot;公共能力生命周期&quot;">​</a></h1><p>状态：当前权威（能力排队与证据路由）。当前可发布 interface 仍由包 <code>package.json</code>、exports、README、声明、源码、测试和发布产物决定；本目录不复制已发布组件的完整 API。</p><h2 id="状态定义" tabindex="-1">状态定义 <a class="header-anchor" href="#状态定义" aria-label="Permalink to &quot;状态定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>不能据此宣称</th></tr></thead><tbody><tr><td>Candidate</td><td>已有消费者问题或来源证据，尚未承诺实施。</td><td>已排期或具备公共边界。</td></tr><tr><td>Planned</td><td>已有已批准计划，等待实施。</td><td>代码、exports 或发布产物存在。</td></tr><tr><td>Ready</td><td>实施前置条件和范围已冻结，可开始执行。</td><td>已实施、已发布或已被消费者采用。</td></tr><tr><td>InProgress</td><td>已有冻结 PRP，实施或独立验收仍在进行中。</td><td>已发布或已被消费者采用。</td></tr><tr><td>Implemented</td><td>已按对应实施记录完成实现；发布与消费者采用须另有证据。</td><td>已进入 npm 或已被任一消费者解析。</td></tr><tr><td>Published</td><td>目标包已有可验证的 release record 与发布产物/正式入口。</td><td>某个消费者已经升级或正在使用该版本。</td></tr><tr><td>Adopted</td><td>指定消费者的 <code>package.json</code>、lockfile 和接入/验收记录证明正在采用。</td><td>其他消费者也采用，或能力已发布。</td></tr><tr><td>Deprecated</td><td>仍保留兼容期，但已有替代入口、迁移边界和退役条件。</td><td>已移除。</td></tr><tr><td>Removed</td><td>公开入口和兼容期已按计划结束，并保留迁移/发布记录。</td><td>历史引用已自动失效。</td></tr></tbody></table><p><code>Implemented</code>、<code>Published</code>、<code>Adopted</code> 是三个独立事实：实施 PRP 的 <code>Executed</code> 只说明该 PRP 已完成，不能替代 release record 或消费者自身的解析证据。</p><h2 id="工作队列与优先级" tabindex="-1">工作队列与优先级 <a class="header-anchor" href="#工作队列与优先级" aria-label="Permalink to &quot;工作队列与优先级&quot;">​</a></h2><p>下一项能力先按以下顺序排队：真实消费者阻塞或兼容风险 → 已确认的跨消费者复用 → 已批准 PRP 的 Ready 项 → 仅有来源线索的 Candidate。每项至少记录所属包、证据、消费者或来源、状态和暂缓边界；没有第二个真实消费者、稳定 Qy interface 或验证入口时，不把业务规则升级为公共能力。</p><p>已发布组件全表、功能缺口、尚未建设的候选顺序和多 renderer 未实现入口统一见 <a href="./component-roadmap">公共组件现状与后续路线</a>。本文件只维护生命周期规则和当前活动/债务摘要，不再用最近一次发布批次冒充完整组件清单。</p><h2 id="当前在制与兼容债务" tabindex="-1">当前在制与兼容债务 <a class="header-anchor" href="#当前在制与兼容债务" aria-label="Permalink to &quot;当前在制与兼容债务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力/债务</th><th>所属包</th><th>状态</th><th>证据与消费者/来源</th><th>暂缓边界</th></tr></thead><tbody><tr><td>QyStatistic</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已完成，根入口、子入口和类型已随 <a href="./../releases/2026-08-10-qynpm-ui-1.0.29">1.0.29</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyRow / QyCol（QyGrid）</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已完成，根入口、子入口和类型已随 <a href="./../releases/2026-08-10-qynpm-ui-1.0.29">1.0.29</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyIcon、QyIconPicker 与图标注册表</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已完成，公开入口已随 <a href="./../releases/2026-08-10-qynpm-ui-1.0.29">1.0.29</a> 发布。</td><td>不将应用图标资产或消费者注册表泛化为已采用能力。</td></tr><tr><td>QyFullscreen</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已完成，公开入口已随 <a href="./../releases/2026-08-10-qynpm-ui-1.0.29">1.0.29</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyLoading V1</td><td><code>@qynpm/hooks</code></td><td>Published</td><td>对应执行记录已完成，runtime、指令、插件和类型入口已随 <a href="./../releases/2026-08-21-qynpm-hooks-1.0.4-ui-1.0.32">2026-08-21 发布记录</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>Qy Feedback Prompt V1</td><td><code>@qynpm/hooks</code></td><td>Published</td><td>Qy-owned prompt options/result、根入口、runtime 和 packed consumer 已通过独立验收，并随 <a href="./../releases/2026-09-03-qynpm-hooks-1.0.5"><code>1.0.5</code></a> 发布。</td><td><code>qy-permission</code> 消费升级与 Element Plus 宿主交互仍须单独验证。</td></tr><tr><td>QyDrawer V1</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已通过独立验收，根/子路径、类型和构建产物已随 <a href="./../releases/2026-08-21-qynpm-hooks-1.0.4-ui-1.0.32">2026-08-21 发布记录</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyResult V1</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应执行记录已完成，根/子路径、类型和构建产物已随 <a href="./../releases/2026-08-21-qynpm-hooks-1.0.4-ui-1.0.32">2026-08-21 发布记录</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyDialog</td><td><code>@qynpm/ui</code></td><td>Published</td><td>新版根/子路径、公开类型和构建产物已随 <a href="./../releases/2026-08-23-qydialog-release-batch">2026-08-23 发布记录</a> 发布；公开名称仍为 <code>QyDialog</code>。</td><td>旧协议由独立 legacy 包承接；消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyIframe</td><td><code>@qynpm/ui</code></td><td>Published</td><td>根/子路径、公开类型和构建产物已随 <a href="./../releases/2026-08-23-qynpm-ui-1.0.34-qyiframe">1.0.34</a> 发布，并通过 registry 精确版本消费验证。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyDialog 旧协议兼容</td><td><code>@qynpm/qy-dialog-legacy</code></td><td>Deprecated</td><td>兼容适配与自包含声明已随 <a href="./../releases/2026-08-23-qydialog-release-batch">1.0.1</a> 发布。</td><td>只承接迁移期旧协议，不向新版 <code>QyDialog</code> 回灌兼容属性。</td></tr><tr><td>QyAddressDialog</td><td><code>@qynpm/qy-address-dialog</code></td><td>Published</td><td>保持既有调用协议的适配版本已随 <a href="./../releases/2026-08-23-qydialog-release-batch">1.0.2</a> 发布。</td><td>消费者采用仍须在对应项目单独验证；大小写重复目录另行治理。</td></tr><tr><td>QyColorPicker V1</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应 PRP 已通过独立验收，结论 <code>QYCOLORPICKER-01 ACCEPT</code>；根/子路径、类型和构建产物已随 <a href="./../releases/2026-08-23-qynpm-ui-1.0.34-qyiframe">1.0.34</a> 发布。</td><td>尚未被消费者采用。</td></tr><tr><td>QyPopconfirm V1</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应 PRP 已通过独立验收，结论 <code>QYPOPCONFIRM-01 ACCEPT</code>；根/子路径、类型和构建产物已随 <a href="./../releases/2026-08-23-qynpm-ui-1.0.34-qyiframe">1.0.34</a> 发布。</td><td>尚未被消费者采用。</td></tr><tr><td>QyWatermark V1</td><td><code>@qynpm/ui</code></td><td>Published</td><td>对应 PRP 已通过独立验收，结论 <code>QYWATERMARK-01 ACCEPT</code>；UI 根/子路径、类型和构建产物已随 <a href="./../releases/2026-08-23-qynpm-ui-1.0.34-qyiframe">1.0.34</a> 发布。</td><td><code>@qynpm/table-schema</code> 的 ImageCell 接入尚未发布，也未迁移旧页面。</td></tr><tr><td>QyContainer / QyAside / QyMain</td><td><code>@qynpm/ui</code></td><td>Published</td><td>公共入口、类型和浏览器验收已完成，并随 <a href="./../releases/2026-08-10-qynpm-ui-1.0.29">1.0.29</a> 发布。</td><td>消费者采用仍须在对应项目单独验证。</td></tr><tr><td>QyDictTag</td><td><code>@qynpm/admin-patterns</code></td><td>Published</td><td>对应执行记录已通过独立验收，根入口、类型和构建产物已随 <a href="./../releases/2026-08-13-components-release-batch">1.0.4</a> 发布。</td><td>尚未被消费者采用，不宣称 Adopted。</td></tr><tr><td>QyRichTextEditor V1</td><td><code>@qynpm/rich-text</code></td><td>Published</td><td>对应执行记录已通过独立验收，根/子入口、类型和构建产物已随 <a href="./../releases/2026-08-13-components-release-batch">1.0.0</a> 发布。</td><td>Quill 只作为内部 adapter；尚未迁移旧消费者，不扩展附件、提及、协同或 Markdown。</td></tr><tr><td>QyRichTextViewer V1</td><td><code>@qynpm/rich-text</code></td><td>Published</td><td>对应执行记录已通过独立验收，Viewer 根/子入口和类型已随 <a href="./../releases/2026-08-13-components-release-batch">1.0.0</a> 发布。</td><td>不创建 Quill 实例，不迁移 <code>RichTextBlock</code> 业务协议，不提供关闭净化的开关；尚未被消费者采用。</td></tr><tr><td>QyExcelPreview V1</td><td><code>@qynpm/excel-preview</code></td><td>Published</td><td>对应执行记录已通过独立验收，根/子入口、类型和构建产物已随 <a href="./../releases/2026-08-13-components-release-batch">1.0.0</a> 发布。</td><td>不解析 xlsx/xls，不调用业务 API，不迁移 qy-workspace；尚未被消费者采用。</td></tr><tr><td>角色人员、属性、材质属性、工艺、基础产品和工序选择器 V1</td><td><code>@qynpm/pickers</code></td><td>Published</td><td>六项 PRP 均已通过独立验收，根/子入口、公开类型和构建产物已随 <a href="./../releases/2026-08-13-components-release-batch">0.0.4</a> 发布。</td><td>不读取用户 store，不硬编码权限、路由或业务 API；尚未迁移消费者。</td></tr><tr><td>QyProcessAttributePicker V1</td><td><code>@qynpm/pickers</code></td><td>Published</td><td>根/子入口、Qy-owned 类型、旧版完整对象复制/粘贴 codec、完整包测试、构建、pack、类型/运行时消费和双视口浏览器矩阵均已通过独立验收，并随 <a href="./../releases/2026-09-03-qynpm-ui-1.0.36-pickers-0.0.5"><code>0.0.5</code></a> 发布。</td><td>尚未迁移消费者；不读取权限/路由，不修改 qy-workspace。</td></tr><tr><td>ERP 表格 runtime adapter</td><td><code>@qynpm/table-schema</code> / <code>@qynpm/table</code></td><td>Candidate</td><td><code>qy-workspace</code> 约 375 个源码文件调用旧 <code>useCol()</code>；权限、确认、消息、列缓存、资料详情和真实 ERP 页面仍有迁移缺口。</td><td>当前整体收益最高；宿主能力不得倒灌到基础 UI，消费者迁移另行授权。</td></tr><tr><td>QyUpload 选择/上传职责收敛</td><td><code>@qynpm/ui</code></td><td>Published</td><td><code>QyUpload</code> 已承接普通文件列表和只选择模式，<code>QyFilePicker</code> 成为 Deprecated 兼容入口，<code>QyImageUpload</code> 保留；聚焦测试、类型消费、构建和文档页运行时验收通过，并随 <a href="./../releases/2026-09-03-qynpm-ui-1.0.36-pickers-0.0.5"><code>1.0.36</code></a> 发布。</td><td>尚未迁移消费者；宿主 adapter 负责鉴权、baseURL、响应归一化和完整 URL。</td></tr><tr><td>QyInput / QyInputTag / QyInputNumber / QyMoneyInput 公共契约</td><td><code>@qynpm/ui</code></td><td>Published</td><td>四个输入组件的根/子路径、Qy-owned 类型、聚焦测试、构建和 packed consumer 已完成，并随 <a href="./../releases/2026-09-03-qynpm-ui-1.0.36-pickers-0.0.5"><code>1.0.36</code></a> 发布。</td><td>尚未迁移消费者；金额语义由 <code>QyMoneyInput</code> 承接，<code>QyInputNumber</code> 保持数字输入语义。</td></tr><tr><td>QyPagination 消费者迁移 adapter</td><td><code>@qynpm/admin-patterns</code> + qy-workspace 私有 adapter</td><td>Candidate</td><td>旧 Pagination 覆盖约 270 个源码文件；现有 QyPagination 已具备核心能力，主要差异是旧 <code>page / limit / pagination</code> 和 auto-scroll 协议。</td><td>先做消费者私有映射和真实页面迁移；无新增证据不扩张公共 interface。</td></tr></tbody></table><p>消费者的角色和各自验收入口见 <a href="./../consumers/README">消费者索引</a>；发布入口和正式解析规则见 <a href="./../contracts/package-exports-and-runtime">包 exports 与宿主 runtime</a>。</p><p>未来可能更换 UI 框架时的包级与组件级分级、当前暂缓决定和新组件设计检查见 <a href="./renderer-migration-readiness">Renderer 迁移准备度盘点</a>；尚未实现的入口形式和启动条件见 <a href="./component-roadmap">公共组件现状与后续路线</a>。二者都不是当前第二 renderer 的实施授权。</p>',12)])])}const m=d(o,[["render",c]]);export{y as __pageData,m as default};
